--
-- Table structure for table `chinese_documents`
--

DROP TABLE IF EXISTS `chinese_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chinese_documents` (
  `document_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `description` mediumtext,
  `content_type` enum('pdf','video','audio','text','image') NOT NULL,
  `content_url` varchar(255) NOT NULL,
  `difficulty_level` enum('beginner','intermediate','advanced') NOT NULL,
  `hsk_level` int DEFAULT NULL,
  `category` enum('grammar','vocabulary','reading','listening','writing') NOT NULL,
  `word_count` int DEFAULT NULL,
  `duration` int DEFAULT NULL COMMENT 'Thời lượng (phút) nếu là audio/video',
  `thumbnail_url` varchar(255) DEFAULT NULL,
  `is_free` tinyint(1) DEFAULT '0',
  `price` decimal(10,2) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`document_id`),
  KEY `difficulty_level` (`difficulty_level`),
  KEY `hsk_level` (`hsk_level`),
  KEY `category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `chinese_documents`
--

LOCK TABLES `chinese_documents` WRITE;
/*!40000 ALTER TABLE `chinese_documents` DISABLE KEYS */;
INSERT INTO `chinese_documents` VALUES (1,'HSK 4 Reading Practice','Bài đọc luyện thi HSK 4','pdf','/documents/hsk4-reading.pdf','intermediate',4,'reading',350,NULL,'/images/giao-trinh-han-ngu-1_1-1748617449484.jpg',1,1.00,'2025-05-20 15:59:51','2025-05-30 22:08:37'),(2,'Basic Chinese Grammar Video','Video giải thích ngữ pháp cơ bản','video','/videos/grammar-basics.mp4','beginner',2,'grammar',8,15,'/images/Chiec-thuyen-ngoai-xa-1-1747734790636.jpg',1,8.00,'2025-05-20 15:59:51','2025-05-20 17:52:34'),(3,'Advanced Listening Audio','Audio luyện nghe trình độ cao','audio','/audio/advanced-listening.mp3','advanced',5,'listening',1,20,'/images/thumbnail-1744427283672.jpg',0,4.90,'2025-05-20 15:59:51','2025-05-20 17:52:01'),(4,'Common Vocabulary List HSK3','Danh sách từ vựng thông dụng cho HSK 3','text','/texts/vocab-hsk3.txt','beginner',3,'vocabulary',120,NULL,'/images/thumbnail-1744427050075.jpg',1,1.00,'2025-05-20 15:59:51','2025-05-20 17:51:53'),(5,' phát triển hán ngữ đọc hiểu trung cấp 2 发展汉语中级阅读 (II)','<p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; font-size: 14.3px; text-align: justify;\"><span style=\"font-size: 12pt;\">&nbsp;Biết được nỗi lo lắng của bạn với môn đọc hiểu tiếng Trung vậy nên hôm nay Tiếng Trung Thượng Hải sẽ giới thiệu đến bạn quyển sách có tên&nbsp;<span style=\"font-weight: 600;\">发展汉语中级阅读 (II)</span>&nbsp;<span style=\"font-weight: 600;\">(Developing Chinese Intermediate Reading Course II)</span>&nbsp;(sách phát triển hán ngữ đọc hiểu trung cấp 2). Được xuất bản tại Đại Học Ngôn Ngữ Bắc Kinh, cung cấp các bài luyện đọc và giải thích từ vựng, ngữ pháp giúp việc đọc của bạn trở nên dễ dàng hơn, nắm chắc điểm cao trong tay trước khi bước vào kỳ thi.</span></p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; font-size: 14.3px; text-align: justify;\"><span style=\"font-size: 12pt;\"