/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `courses` (
  `course_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) NOT NULL,
  `description` mediumtext,
  `thumbnail_url` varchar(255) DEFAULT NULL,
  `difficulty_level` enum('hsk1','hsk2','hsk3','hsk4','hsk5','hsk6') DEFAULT NULL,
  `estimated_duration` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `is_free` tinyint(1) DEFAULT '0',
  `price` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`course_id`),
  CONSTRAINT `CHK_Price` CHECK (((`is_free` = true) or (`price` > 0)))
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng thông tin các khóa học';
