INSERT INTO `courses` VALUES (93,'HÁN  1 GIÁO TRÌNH HÁN NGỮ QUYỀN 1','<p style=\"margin-right: 0px; margin-bottom: 25px; margin-left: 0px; padding: 0px; list-style: none; border: 0px; outline: none; line-height: 1.75; font-size: 18px; color: rgb(44, 47, 52); font-family: Arial, Helvetica, sans-serif;\">Dưới đây,&nbsp;<a href=\"https://chinese.edu.vn/\" rel=\"nofollow noopener\" target=\"_blank\" style=\"color: rgb(245, 122, 32); padding: 0px; margin: 0px; list-style: none; border: 0px; outline: none; transition: 0.15s;\">tiếng Trung Chinese</a>&nbsp;xin được giới thiệu với các bạn nội dung Giáo trình Hán ngữ quyển 1 Bài 1: Xin chào！你好！d</p><p style=\"margin-right: 0px; margin-bottom: 25px; margin-left: 0px; padding: 0px; list-style: none; border: 0px; outline: none; line-height: 1.75; font-size: 18px; color: rgb(44, 47, 52); font-family: Arial, Helvetica, sans-serif;\">Bài 1 Giáo trình Hán ngữ 1 sẽ giúp các bạn làm quen với kiến thức cơ bản của tiếng Trung như Ngữ âm, Từ vựng,&nbsp;<a href=\"https://tiengtrungonline.com/ngu-phap-tieng-trung\" target=\"_blank\" rel=\"noopener\" style=\"color: rgb(245, 122, 32); padding: 0px; margin: 0px; list-style: none; border: 0px; outline: none; transition: 0.15s;\">Ngữ pháp tiếng Trung</a>, cách viết chữ Hán.</p><p style=\"margin-right: 0px; margin-bottom: 25px; margin-left: 0px; padding: 0px; list-style: none; border: 0px; outline: none; line-height: 1.75; font-size: 18px; color: rgb(44, 47, 52); font-family: Arial, Helvetica, sans-serif; text-align: right;\">→ Tải [ MP3, PDF ] của&nbsp;<a href=\"https://tiengtrungonline.com/giao-trinh/han-ngu-6-quyen/quyen-1\" style=\"color: rgb(245, 122, 32); padding: 0px; margin: 0px; list-style: none; border: 0px; outline: none; transition: 0.15s;\">Giáo trình Hán ngữ Quyển 1</a></p><div id=\"ez-toc-container\" class=\"ez-toc-v2_0_74 ez-toc-wrap-center counter-hierarchy ez-toc-counter ez-toc-custom ez-toc-container-direction\" style=\"padding: 10px 20px 10px 10px; margin-bottom: 1em; list-s