INSERT INTO `grammar` VALUES (1,'是...的','Subject + 是 + Verb + 的','Used to emphasize past actions or facts.','我是昨天来的。','Wǒ shì zuótiān lái de.','I came yesterday.','intermediate',4),(2,'一边...一边...','Subject + 一边 + Verb1 + 一边 + Verb2','Used to indicate two simultaneous actions.','他一边吃饭一边看电视。','Tā yībiān chīfàn yībiān kàn diànshì.','He eats while watching TV.','beginner',3),(3,'是...的','Subject + 是 + Verb + 的','Used to emphasize past actions or facts.','我是昨天来的。','Wǒ shì zuótiān lái de.','I came yesterday.','intermediate',4),(4,'一边...一边...','Subject + 一边 + Verb1 + 一边 + Verb2','Used to indicate two simultaneous actions.','他一边吃饭一边看电视。','Tā yībiān chīfàn yībiān kàn diànshì.','He eats while watching TV.','beginner',3);
